    }
    config['etcd'] = {
        'tls': 'False',
        'authentication': 'False',
        'authorization': 'False'
    }
    config['docs'] = {
        'url': 'https://example.com/docs'
    }
    config['log'] = {
        'level': 'INFO',
        'format': '%(asctime)s - %(levelname)s - %(message)s'
    }
    with open('config.ini', 'w') as configfile:
        config.write(configfile)
    return 'config.ini'

